#include <capstone/capstone.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
static bool ck(csh h,const uint8_t*b,unsigned id,const char*m,const char*o,bool flags){cs_insn*i=NULL;bool ok=cs_disasm(h,b,9,0,1,&i)==1;if(ok){const cs_x86*x=&i->detail->x86;const cs_x86_op*mem=x->operands[0].type==X86_OP_MEM?&x->operands[0]:&x->operands[1];const cs_x86_op*reg=x->operands[0].type==X86_OP_REG?&x->operands[0]:&x->operands[1];ok=i->id==id&&!strcmp(i->mnemonic,m)&&!strcmp(i->op_str,o)&&x->op_count==2&&mem->size==64&&mem->access==CS_AC_READ&&reg->size==8&&reg->access==CS_AC_READ&&(flags?x->eflags!=0:x->eflags==0);}if(i)cs_free(i,1);return ok;}
int main(void){const uint8_t a[]={0x64,0x62,0x0c,0x7f,8,0xf8,0x54,0xb5,0x20},b[]={0x64,0x62,0x0c,0x7e,8,0xf8,0x54,0xb5,0x20},c[]={0x64,0x62,0x0c,0x7d,8,0xf8,0x54,0xb5,0x20};uint8_t bad[9];csh h;cs_insn*i=NULL;bool ok=true;if(cs_open(CS_ARCH_X86,CS_MODE_64,&h))return 1;cs_option(h,CS_OPT_DETAIL,CS_OPT_ON);ok&=ck(h,a,X86_INS_ENQCMD,"enqcmd","r26, zmmword ptr fs:[r29 + r14*4 + 0x20]",true);ok&=ck(h,b,X86_INS_ENQCMDS,"enqcmds","r26, zmmword ptr fs:[r29 + r14*4 + 0x20]",true);ok&=ck(h,c,X86_INS_MOVDIR64B,"movdir64b","r26, zmmword ptr fs:[r29 + r14*4 + 0x20]",false);cs_option(h,CS_OPT_SYNTAX,CS_OPT_SYNTAX_ATT);ok&=ck(h,a,X86_INS_ENQCMD,"enqcmd","%fs:0x20(%r29,%r14,4), %r26",true);cs_option(h,CS_OPT_SYNTAX,CS_OPT_SYNTAX_INTEL);memcpy(bad,a,9);for(unsigned k=0;k<4;k++){bad[4]=(uint8_t[]){0,4,0x18,0x28}[k];if(cs_disasm(h,bad,9,0,1,&i)){ok=false;cs_free(i,1);i=NULL;}}memcpy(bad,a,9);bad[6]=0xd3;if(cs_disasm(h,bad,7,0,1,&i)){ok=false;cs_free(i,1);}cs_close(&h);if(!ok)fprintf(stderr,"APX enqueue failure\n");return ok?0:1;}
